// The displayed cases are generated by the project Node rehearsal. This page
// never calls a tool, requests approval, or executes an outside service.
export function chooseRehearsalCase(report, requested, recipient = "outside") {
  if (!report || report.protocol !== "aml-guarded-tool-rehearsal/2" || !Array.isArray(report.cases)) {
    throw new TypeError("Invalid guarded tool rehearsal report");
  }
  const fallback = recipient === "team" ? "approved_route" : "changed_destination";
  const id = report.cases.some(item => item.id === requested) ? requested : fallback;
  if (!report.cases.some(item => item.id === id)) throw new Error("Missing first-contact case");
  return id;
}

export function rehearsalCaseUrl(currentUrl, id, report) {
  if (!report?.cases?.some(item => item.id === id)) throw new RangeError("Unknown rehearsal case");
  const url = new URL(currentUrl);
  url.searchParams.set("case", id);
  url.hash = "rehearsal";
  return url.href;
}

export function rehearsalCasePayload(report, id) {
  const item = report?.cases?.find(entry => entry.id === id);
  if (!item) throw new RangeError("Unknown rehearsal case");
  return { protocol: report.protocol, provenance: report.provenance, scope: report.scope, case: item };
}

export function nextRehearsalCaseIndex(key, index, count) {
  if (key === "Home") return 0;
  if (key === "End") return count - 1;
  if (key === "ArrowRight" || key === "ArrowDown") return (index + 1) % count;
  if (key === "ArrowLeft" || key === "ArrowUp") return (index + count - 1) % count;
  return null;
}

if (typeof document !== "undefined" && document.getElementById("rehearsal")) {
  const $ = id => document.getElementById(id);
  const params = new URLSearchParams(location.search);
  const recipient = params.get("recipient") === "team" ? "team" : "outside";
  $("selected-route").textContent = `send_message → ${recipient === "team" ? "team" : "outsider"}@example.test`;
  $("selected-result").textContent = recipient === "team" ?
    "The exact rule matches, but a real host still needs approval bound to this proposal before dispatch." :
    "The outside destination has no exact rule and cannot reach the callback.";
  $("case-link").href = `action-lab.html?scenario=${recipient === "team" ? "send" : "changed"}`;

  document.querySelectorAll("[data-copy]").forEach(button => button.addEventListener("click", async () => {
    const id = button.dataset.copy;
    try {
      await navigator.clipboard.writeText($(id).textContent.trim() + "\n");
      $(id + "-status").textContent = "Copied.";
    } catch {
      $(id + "-status").textContent = "Clipboard unavailable. Select the text above to copy it.";
    }
  }));

  const metric = value => {
    const span = document.createElement("span");
    span.textContent = value;
    return span;
  };
  const attemptCard = (attempt, index) => {
    const card = document.createElement("div");
    card.className = "attempt";
    card.dataset.tone = attempt.execution_status === "dispatched" ? "go" :
      attempt.execution_status === "unknown" ? "hold" : "stop";
    const label = document.createElement("small");
    label.textContent = `ATTEMPT ${String(index + 1).padStart(2, "0")} · PLAN ${attempt.policy_decision.toUpperCase().replaceAll("_", " ")}`;
    const status = document.createElement("strong");
    status.textContent = attempt.execution_status.toUpperCase();
    const reason = document.createElement("code");
    reason.textContent = `receipt.reason = ${attempt.reason}`;
    const digest = document.createElement("code");
    digest.textContent = `proposal SHA-256: ${attempt.proposal_sha256}`;
    const result = document.createElement("code");
    if (attempt.result) result.textContent = `Fixture target: ${attempt.result.would_send_to}`;
    const traceLabel = document.createElement("small");
    traceLabel.className = "trace-label";
    traceLabel.textContent = "HOST HOOK TRACE";
    const trace = document.createElement("ol");
    trace.className = "hook-trace";
    const events = attempt.host_hook_events.length ? attempt.host_hook_events : ["No host-owned hook invoked"];
    for (const event of events) {
      const step = document.createElement("li");
      if (!attempt.host_hook_events.length) step.className = "none";
      step.textContent = event;
      trace.append(step);
    }
    card.append(label, status, reason, digest);
    if (attempt.result) card.append(result);
    card.append(traceLabel, trace);
    return card;
  };

  $("copy-case-command").addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText($("case-command").textContent + "\n");
      $("case-copy-status").textContent = "Case command copied.";
    } catch {
      $("case-copy-status").textContent = "Clipboard unavailable. Select the command above to copy it.";
    }
  });

  fetch("guarded-tool-rehearsal.json?v=d6e451d28588").then(response => {
    if (!response.ok) throw new Error("Report request failed");
    return response.json();
  }).then(report => {
    const initial = chooseRehearsalCase(report, params.get("case"), recipient);
    const sharedCase = report.cases.some(item => item.id === params.get("case"));
    $("case-count-label").textContent = `HOST REHEARSAL / ${report.cases.length} CONTROLLED CASES`;
    const buttons = report.cases.map((item, index) => {
      const button = document.createElement("button");
      button.type = "button";
      button.dataset.case = item.id;
      const statuses = item.attempts.map(attempt => attempt.execution_status);
      button.dataset.tone = statuses.includes("unknown") ? "hold" :
        statuses.every(status => status === "blocked") ? "stop" : "go";
      const state = document.createElement("span");
      state.textContent = `${String(index + 1).padStart(2, "0")} / ${statuses.join(" → ").toUpperCase()}`;
      button.append(state, document.createTextNode(item.title));
      button.addEventListener("click", () => show(item.id, true));
      button.addEventListener("keydown", event => {
        const next = nextRehearsalCaseIndex(event.key, index, report.cases.length);
        if (next === null) return;
        event.preventDefault();
        buttons[next].focus();
        show(report.cases[next].id, true);
      });
      return button;
    });
    $("case-picker").replaceChildren(...buttons);
    let selectedCase = initial;
    function show(id, updateUrl) {
      const item = report.cases.find(entry => entry.id === id);
      selectedCase = id;
      buttons.forEach(button => {
        const selected = button.dataset.case === id;
        button.setAttribute("aria-pressed", String(selected));
        button.tabIndex = selected ? 0 : -1;
      });
      $("case-title").textContent = item.title;
      $("case-change").textContent = item.change;
      if (sharedCase || updateUrl) {
        $("route-label").textContent = "SELECTED HOST REHEARSAL";
        $("selected-route").textContent = item.title;
        $("selected-result").textContent = item.change;
        $("case-link").textContent = "Jump to selected result ↓";
        $("case-link").href = "#case-title";
      }
      $("case-host-move").textContent = item.host_move;
      $("case-attempts").replaceChildren(...item.attempts.map(attemptCard));
      $("case-metrics").replaceChildren(
        metric(`Approval requests: ${item.approval_requests}`),
        metric(`Claim attempts: ${item.claim_attempts}`),
        metric(`Claims consumed: ${item.claims_consumed}`),
        metric(`Fixture callbacks: ${item.callback_count}`),
        ...(item.fixture_state_changes ? [metric(`In-memory fixture writes: ${item.fixture_state_changes}`)] : []),
        ...(item.caller_destination_after_approval ?
          [metric(`Caller changed to: ${item.caller_destination_after_approval}`)] : [])
      );
      $("case-command").textContent = `node pilots/action-boundary/guarded-tool-rehearsal.mjs --case ${item.id}`;
      $("case-copy-status").textContent = "";
      if (updateUrl) history.replaceState(null, "", rehearsalCaseUrl(location.href, id, report));
    }
    $("copy-case-link").addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(rehearsalCaseUrl(location.href, selectedCase, report));
        $("case-copy-status").textContent = "Case link copied.";
      } catch {
        $("case-copy-status").textContent = "Clipboard unavailable. Copy the address in your browser to share this case.";
      }
    });
    $("copy-case-json").addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(JSON.stringify(rehearsalCasePayload(report, selectedCase), null, 2) + "\n");
        $("case-copy-status").textContent = "Project fixture JSON copied. Record your checkout commit when sharing.";
      } catch {
        $("case-copy-status").textContent = "Clipboard unavailable. Run the case command above to print its JSON.";
      }
    });
    show(initial, false);
  }).catch(() => {
    $("case-title").textContent = "Report unavailable here.";
    $("case-change").textContent = "Run the local rehearsal command above or inspect the project source to check these outcomes.";
  });
}
